	default Color graphColor()
	{
		return DEFAULT_LINE_COLOR;
	}

	@ConfigItem(
		keyName = "line2Color",
		name = "Line 2 color",
		description = "Color of the second, independent odds line",
		position = 2
	)
	default Color line2Color()
	{
		return DEFAULT_LINE2_COLOR;
