public class MarketPainterTest
{
	// Set DROPMARKET_PREVIEW_DIR=/some/dir to dump PNGs of each state for eyeballing.
	private static final String PREVIEW_DIR = System.getenv("DROPMARKET_PREVIEW_DIR");
	private static final int W = DropMarketOverlay.DEFAULT_SIZE.width;
	private static final int H = DropMarketOverlay.DEFAULT_SIZE.height;

	private static final class TestConfig implements DropMarketConfig
	{
		Color graphColor = DEFAULT_LINE_COLOR;
		Color line2Color = DEFAULT_LINE2_COLOR;
		Color negativeDeltaColor1 = DEFAULT_NEGATIVE_DELTA_COLOR;
		Color negativeDeltaColor2 = DEFAULT_NEGATIVE_DELTA_COLOR;
		boolean showBar1;
		boolean showBar2;
		boolean showDualLine;
		Color bar1Color = DEFAULT_BAR1_COLOR;
		Color bar2Color = DEFAULT_BAR2_COLOR;
		Color bar1TextColor = Color.WHITE;
		Color bar2TextColor = Color.BLACK;
		String bar1Text = "";
		String bar2Text = "";

		@Override
		public Color graphColor()
		{
			return graphColor;
		}

		@Override
		public Color line2Color()
		{
			return line2Color;
		}

		@Override
		public Color negativeDeltaColor1()
		{
			return negativeDeltaColor1;
		}

		@Override
		public Color negativeDeltaColor2()
		{
			return negativeDeltaColor2;
		}

		@Override
		public boolean showBar1()
		{
			return showBar1;
		}

		@Override
		public boolean showBar2()
		{
			return showBar2;
		}

		@Override
		public boolean showDualLine()
		{
			return showDualLine;
		}

		@Override
		public Color bar1Color()
		{
			return bar1Color;
		}

		@Override
		public Color bar2Color()
		{
			return bar2Color;
		}

		@Override
		public Color bar1TextColor()
		{
			return bar1TextColor;
		}

		@Override
		public Color bar2TextColor()
		{
			return bar2TextColor;
		}

		@Override
		public String bar1Text()
		{
			return bar1Text;
		}

		@Override
		public String bar2Text()
		{
			return bar2Text;
		}
	}

	private static BufferedImage render(String title, boolean resolved, long nowTick, int w, int h) throws Exception
	{
		return render(title, resolved, nowTick, w, h, new TestConfig(), null, 0);
	}

	private static BufferedImage render(String title, boolean resolved, long nowTick, int w, int h,
		TestConfig config, MarketGraph polyGraph, long volumePop) throws Exception
	{
		MarketGraph graph = new MarketGraph(new Random(1234));
		graph.reset();
		if (resolved)
		{
			graph.pinToCertain();
			graph.pinToCertain();
		}

		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		MarketPainter.paint(g, w, h, title, graph, polyGraph, config, resolved, nowTick,
			FontManager.getRunescapeBoldFont(), FontManager.getRunescapeSmallFont(), "3 KC", true, volumePop, 12, 9);
		g.dispose();
		return img;
	}

	private static void save(BufferedImage img, String name) throws Exception
	{
		if (PREVIEW_DIR != null)
		{
			ImageIO.write(img, "png", new File(PREVIEW_DIR, name + ".png"));
		}
	}

	private static boolean containsColor(BufferedImage img, Color c)
	{
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) & 0xFFFFFF) == (c.getRGB() & 0xFFFFFF))
				{
					return true;
				}
			}
		}
		return false;
	}

	@Test
	public void drawsLineInGraphColor() throws Exception
	{
		BufferedImage img = render("Zulrah drops Tanzanite fang", false, 0, W, H);
		save(img, "market");
		assertTrue(containsColor(img, DropMarketConfig.DEFAULT_LINE_COLOR));
	}

	@Test
	public void resolvedFlashesRaidPurple() throws Exception
	{
		BufferedImage on = render("Chambers of Xeric drops Twisted bow", true, 0, W, H);
		BufferedImage off = render("Chambers of Xeric drops Twisted bow", true, 2, W, H);
		save(on, "resolved-flash-on");
		save(off, "resolved-flash-off");
		assertTrue(containsColor(on, MarketPainter.RAID_PURPLE));
	}

	@Test
	public void longTitlesAndOtherSizesRender() throws Exception
	{
		save(render(DropMarketPlugin.LIVE_ODDS, false, 7, W, H), "live-odds");
		save(render("Theatre of Blood drops Sanguinesti staff and an extremely long suffix", false, 0, W, H),
			"long-title");
		save(render("Tombs of Amascut drops Tumeken's shadow", false, 0, 320, 160), "large");
		save(render("Goblin drops Anything good", false, 0, 120, 80), "tiny");
	}

	@Test
	public void brandBarsRender() throws Exception
	{
		MarketGraph poly = new MarketGraph(new Random(99));
		poly.reset();
		TestConfig config = new TestConfig();
		config.showBar1 = true;
		config.showBar2 = true;
		config.showDualLine = true;
		config.bar1Text = "Line 1 Odds";
		config.bar2Text = "Line 2 Odds";
		BufferedImage img = render("Zulrah drops Tanzanite fang", false, 0, W, H, config, poly, 1_400_000L);
		save(img, "brand-bars");
		assertTrue(containsColor(img, DropMarketConfig.DEFAULT_LINE_COLOR));
	}
}

package com.dropmarket;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class MarketPickerTest
{
	private static final long THRESHOLD = 250_000;
	private static final Map<String, Long> PRICES = ImmutableMap.of(
		"Tanzanite fang", 1_500_000L,
		"Magic fang", 1_200_000L,
		"Bronze spear", 30L,
		"Leaf-bladed battleaxe", 120_000L);

	private static long price(String item)
	{
		return PRICES.getOrDefault(item, -1L);
	}

	private static String pick(boolean petFirst, Set<String> locked, String... table)
	{
		return MarketPicker.pick(Arrays.asList(table), petFirst, THRESHOLD, MarketPickerTest::price, locked::contains);
	}

	@Test
	public void valuableTradeableWins()
	{
		assertEquals("Tanzanite fang",
			pick(false, ImmutableSet.of("Pet snakeling"), "Tanzanite fang", "Magic fang", "Pet snakeling"));
	}

	@Test
	public void cheapMonsterWithLockedUntradeableChasesIt()
	{
		assertEquals("Goblin champion scroll",
			pick(false, ImmutableSet.of("Goblin champion scroll"), "Bronze spear", "Goblin champion scroll"));
	}

	@Test
	public void cheapMonsterWithEverythingUnlockedIsLiveOdds()
	{
		assertNull(pick(false, ImmutableSet.of(), "Bronze spear", "Goblin champion scroll"));
		assertNull(pick(false, ImmutableSet.of(), "Leaf-bladed battleaxe"));
	}

	@Test
	public void petFirstPrefersLockedPetThenFallsBack()
	{
		assertEquals("Rock golem", pick(true, ImmutableSet.of("Rock golem"), "Rock golem"));
		assertNull(pick(true, ImmutableSet.of(), "Rock golem"));
		assertEquals("Tanzanite fang", pick(true, ImmutableSet.of(), "Phoenix", "Tanzanite fang"));
	}

	@Test
	public void firstLockedSlotInTableOrderIsChosen()
	{
		assertEquals("Fire cape",
			pick(false, ImmutableSet.of("Fire cape", "Tzrek-jad"), "Fire cape", "Tzrek-jad"));
		assertEquals("Tzrek-jad", pick(false, ImmutableSet.of("Tzrek-jad"), "Fire cape", "Tzrek-jad"));
	}
}

package com.dropmarket;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import java.util.Arrays;
import org.junit.Test;

public class WikiDropTableClientTest
{
	private static String row(String item, String rarity, long value)
	{
		String drop = "{\\\"Rarity\\\":\\\"" + rarity + "\\\",\\\"Drop Value\\\":" + value
			+ ",\\\"Dropped item\\\":\\\"" + item + "\\\"}";
		return "{\"item_name\":\"" + item + "\",\"page_name\":\"Zulrah\",\"drop_json\":\"" + drop + "\"}";
	}

	@Test
	public void parseSkipsAlwaysDropsAndSortsByValue()
	{
		String json = "{\"bucketQuery\":\"...\",\"bucket\":["
			+ row("Zulrah's scales", "Always", 12) + ","
			+ row("Magic fang", "1/1,024", 61200) + ","
			+ row("Tanzanite fang", "1/1,024", 66000) + ","
			+ row("Magic fang", "1/1,024", 100) + ","
			+ row("Pet snakeling", "1/4,000", 0)
			+ "]}";

		WikiDropTableClient client = new WikiDropTableClient(null, new Gson(), null);
		assertEquals(Arrays.asList("Tanzanite fang", "Magic fang", "Pet snakeling"), client.parse(json));
	}

	@Test
	public void parseHandlesMissingBucket()
	{
		WikiDropTableClient client = new WikiDropTableClient(null, new Gson(), null);
		assertEquals(0, client.parse("{\"error\":\"bad query\"}").size());
	}
}
